import 'media_kind.dart';

enum UserMediaStateCategory { library, progress, rating }

final class UserMediaStateEvent<TPayload> {
  UserMediaStateEvent({
    required this.mediaKind,
    required this.entityId,
    required this.category,
    required DateTime updatedAt,
    required this.tombstone,
    required this.partial,
    required this.payload,
  }) : updatedAt = updatedAt.toUtc() {
    if (entityId.isEmpty) {
      throw ArgumentError.value(entityId, 'entityId', 'Must not be empty.');
    }
  }

  final MediaKind mediaKind;
  final String entityId;
  final UserMediaStateCategory category;
  final DateTime updatedAt;
  final bool tombstone;
  final bool partial;
  final TPayload? payload;
}

List<UserMediaStateEvent<TPayload>> latestUserMediaStateEvents<TPayload>(
  Iterable<UserMediaStateEvent<TPayload>> events,
) {
  final latest =
      <
        (MediaKind, String, UserMediaStateCategory),
        UserMediaStateEvent<TPayload>
      >{};
  for (final event in events) {
    final key = (event.mediaKind, event.entityId, event.category);
    final current = latest[key];
    if (current == null || !event.updatedAt.isBefore(current.updatedAt)) {
      latest[key] = event;
    }
  }

  final ordered = latest.values.toList()
    ..sort((left, right) => right.updatedAt.compareTo(left.updatedAt));
  return List<UserMediaStateEvent<TPayload>>.unmodifiable(ordered);
}

import 'package:goanime_core/goanime_core.dart';
import 'package:test/test.dart';

void main() {
  test('MediaDownloadJob preserves extensible lifecycle and typed payload', () {
    final job = MediaDownloadJob<_Payload>(
      mediaKind: MediaKind.manga,
      jobId: 'download-1',
      entityId: 'work-1',
      phase: MediaDownloadJobPhase.verifying,
      progress: MediaDownloadProgress(
        bytesReceived: 75,
        expectedBytes: 100,
        fraction: 0.75,
      ),
      payload: const _Payload('chapter-package'),
    );

    expect(job.mediaKind, MediaKind.manga);
    expect(job.jobId, 'download-1');
    expect(job.entityId, 'work-1');
    expect(job.phase, MediaDownloadJobPhase.verifying);
    expect(job.progress.bytesReceived, 75);
    expect(job.progress.expectedBytes, 100);
    expect(job.progress.fraction, 0.75);
    expect(job.payload.value, 'chapter-package');
  });

  test(
    'download progress accepts unknown totals without inventing a fraction',
    () {
      final progress = MediaDownloadProgress(bytesReceived: 512);

      expect(progress.expectedBytes, isNull);
      expect(progress.fraction, isNull);
    },
  );

  test('download identities and progress values are validated', () {
    expect(
      () => MediaDownloadJob<int>(
        mediaKind: MediaKind.anime,
        jobId: '',
        entityId: 'anime-1',
        phase: MediaDownloadJobPhase.queued,
        progress: MediaDownloadProgress(bytesReceived: 0),
        payload: 1,
      ),
      throwsArgumentError,
    );
    expect(
      () => MediaDownloadJob<int>(
        mediaKind: MediaKind.anime,
        jobId: 'job-1',
        entityId: '',
        phase: MediaDownloadJobPhase.queued,
        progress: MediaDownloadProgress(bytesReceived: 0),
        payload: 1,
      ),
      throwsArgumentError,
    );
    expect(() => MediaDownloadProgress(bytesReceived: -1), throwsArgumentError);
    expect(
      () => MediaDownloadProgress(bytesReceived: 1, expectedBytes: 0),
      throwsArgumentError,
    );
    expect(
      () => MediaDownloadProgress(bytesReceived: 1, fraction: 1.1),
      throwsArgumentError,
    );
  });
}

final class _Payload {
  const _Payload(this.value);

  final String value;
}

import 'package:goanime_core/goanime_core.dart';
import 'package:test/test.dart';

void main() {
  test(
    'MediaHistoryDataSource exposes a neutral refresh-aware list contract',
    () async {
      final source = _FakeHistoryDataSource();

      expect(await source.load(forceRefresh: false), ['cached']);
      expect(await source.load(forceRefresh: true), ['fresh']);
      expect(source.refreshIntents, [false, true]);
    },
  );
}

final class _FakeHistoryDataSource implements MediaHistoryDataSource<String> {
  final List<bool> refreshIntents = <bool>[];

  @override
  Future<List<String>> load({required bool forceRefresh}) async {
    refreshIntents.add(forceRefresh);
    return forceRefresh ? <String>['fresh'] : <String>['cached'];
  }
}

