import 'package:goanime_core/goanime_core.dart';
import 'package:test/test.dart';

void main() {
  test('rejects providers from the wrong media kind', () {
    final entry = _Entry(
      providerKey: ProviderKey.manga('source'),
      displayName: 'Source',
    );

    expect(
      () => MediaProviderRegistryValidator.validateAndIndexBy<_Entry>(
        [entry],
        keyOf: (value) => value.providerKey,
        displayNameOf: (value) => value.displayName,
        expectedMedia: MediaKind.anime,
      ),
      throwsStateError,
    );
  });

  test(
    'rejects empty operation declarations when capabilities are required',
    () {
      final entry = _Entry(
        providerKey: ProviderKey.anime('source'),
        displayName: 'Source',
      );

      expect(
        () => MediaProviderRegistryValidator.validateAndIndexBy<_Entry>(
          [entry],
          keyOf: (value) => value.providerKey,
          displayNameOf: (value) => value.displayName,
          expectedMedia: MediaKind.anime,
          operationsOf: (_) => const <ProviderOperation>{},
        ),
        throwsStateError,
      );
    },
  );

  test('rejects operations that belong to another media kind', () {
    final entry = _Entry(
      providerKey: ProviderKey.manga('source'),
      displayName: 'Source',
    );

    expect(
      () => MediaProviderRegistryValidator.validateAndIndexBy<_Entry>(
        [entry],
        keyOf: (value) => value.providerKey,
        displayNameOf: (value) => value.displayName,
        expectedMedia: MediaKind.manga,
        operationsOf: (_) => const {ProviderOperation.playback},
      ),
      throwsStateError,
    );
  });

  test('requires policy when the domain declares it mandatory', () {
    final entry = _Entry(
      providerKey: ProviderKey.manga('source'),
      displayName: 'Source',
    );

    expect(
      () => MediaProviderRegistryValidator.validateAndIndexBy<_Entry>(
        [entry],
        keyOf: (value) => value.providerKey,
        displayNameOf: (value) => value.displayName,
        expectedMedia: MediaKind.manga,
        operationsOf: (_) => const {ProviderOperation.search},
        requiresPolicy: (_) => true,
        policyKeyOf: (_) => null,
      ),
      throwsStateError,
    );
  });

  test('rejects policy mapped to a different provider key', () {
    final entry = _Entry(
      providerKey: ProviderKey.manga('source'),
      displayName: 'Source',
    );

    expect(
      () => MediaProviderRegistryValidator.validateAndIndexBy<_Entry>(
        [entry],
        keyOf: (value) => value.providerKey,
        displayNameOf: (value) => value.displayName,
        expectedMedia: MediaKind.manga,
        operationsOf: (_) => const {ProviderOperation.search},
        requiresPolicy: (_) => true,
        policyKeyOf: (_) => ProviderKey.manga('other-source'),
      ),
      throwsStateError,
    );
  });
}

final class _Entry implements MediaProviderRegistryEntry {
  const _Entry({required this.providerKey, required this.displayName});

  @override
  final ProviderKey providerKey;

  @override
  final String displayName;
}

import 'package:goanime_core/goanime_core.dart';
import 'package:test/test.dart';

void main() {
  test('UserMediaStateEvent preserves typed payload and domain metadata', () {
    final event = UserMediaStateEvent<_Payload>(
      mediaKind: MediaKind.anime,
      entityId: 'anime-1',
      category: UserMediaStateCategory.progress,
      updatedAt: DateTime.parse('2026-08-24T08:00:00-03:00'),
      tombstone: false,
      partial: true,
      payload: const _Payload('playback'),
    );

    expect(event.mediaKind, MediaKind.anime);
    expect(event.entityId, 'anime-1');
    expect(event.category, UserMediaStateCategory.progress);
    expect(event.updatedAt, DateTime.utc(2026, 8, 24, 11));
    expect(event.tombstone, isFalse);
    expect(event.partial, isTrue);
    expect(event.payload!.value, 'playback');
  });

  test('tombstone envelopes can omit a domain payload', () {
    final event = UserMediaStateEvent<Object?>(
      mediaKind: MediaKind.manga,
      entityId: 'work-1',
      category: UserMediaStateCategory.library,
      updatedAt: DateTime.utc(2026, 8, 24),
      tombstone: true,
      partial: true,
      payload: null,
    );

    expect(event.tombstone, isTrue);
    expect(event.payload, isNull);
  });

  test(
    'latestUserMediaStateEvents deduplicates each category independently',
    () {
      final library = UserMediaStateEvent<int>(
        mediaKind: MediaKind.anime,
        entityId: 'anime-1',
        category: UserMediaStateCategory.library,
        updatedAt: DateTime.utc(2026, 8, 24, 9),
        tombstone: false,
        partial: true,
        payload: 1,
      );
      final olderProgress = UserMediaStateEvent<int>(
        mediaKind: MediaKind.anime,
        entityId: 'anime-1',
        category: UserMediaStateCategory.progress,
        updatedAt: DateTime.utc(2026, 8, 24, 10),
        tombstone: false,
        partial: true,
        payload: 2,
      );
      final newerProgress = UserMediaStateEvent<int>(
        mediaKind: MediaKind.anime,
        entityId: 'anime-1',
        category: UserMediaStateCategory.progress,
        updatedAt: DateTime.utc(2026, 8, 24, 11),
        tombstone: true,
        partial: true,
        payload: 3,
      );

      final result = latestUserMediaStateEvents(<UserMediaStateEvent<int>>[
        olderProgress,
        library,
        newerProgress,
      ]);

      expect(result, hasLength(2));
      expect(result.first.category, UserMediaStateCategory.progress);
      expect(result.first.payload, 3);
      expect(result.first.tombstone, isTrue);
      expect(result.last.category, UserMediaStateCategory.library);
    },
  );

  test('empty entity identity is rejected', () {
    expect(
      () => UserMediaStateEvent<int>(
        mediaKind: MediaKind.anime,
        entityId: '',
        category: UserMediaStateCategory.rating,
        updatedAt: DateTime.utc(2026, 8, 24),
        tombstone: false,
        partial: true,
        payload: 5,
      ),
      throwsArgumentError,
    );
  });
}

final class _Payload {
  const _Payload(this.value);

  final String value;
}

import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

void main() {
  test(
    'Anime download manager delegates queue concurrency to shared coordinator',
    () {
      final source = File(
        'lib/services/download/download_queue_manager.dart',
      ).readAsStringSync();

      expect(source, contains('DownloadQueueCoordinator<String>'));
      expect(source, contains('DownloadConcurrencyPolicy'));
      expect(source, isNot(contains('int _activeDownloadCount')));
      expect(source, isNot(contains('int _maxConcurrentDownloads')));
    },
  );

  test('Anime queued cancellation removes shared pending work', () {
    final source = File(
      'lib/services/download/download_queue_manager.dart',
    ).readAsStringSync();

    expect(source, contains('_queueCoordinator.cancel(id)'));
    expect(source, contains('_queueCoordinator.isKnown(download.id)'));
  });
}

import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

void main() {
  test(
    'shared download job stays domain-neutral and adapters preserve states',
    () {
      final core = File(
        'packages/goanime_core/lib/src/media/media_download_job.dart',
      ).readAsStringSync();
      final anime = File(
        'lib/services/media/anime_download_job_adapter.dart',
      ).readAsStringSync();
      final manga = File(
        'lib/services/media/manga_download_job_adapter.dart',
      ).readAsStringSync();

      expect(core, contains('MediaDownloadJob<TPayload>'));
      expect(core, contains('verifying'));
      expect(core, isNot(contains('DownloadItem')));
      expect(core, isNot(contains('MangaDownloadRecord')));
      expect(core, isNot(contains('Episode')));
      expect(core, isNot(contains('Chapter')));

      expect(anime, contains('DownloadStatus.downloading'));
      expect(anime, contains('MediaDownloadJobPhase.transferring'));
      expect(anime, isNot(contains('MangaDownloadState')));

      expect(manga, contains('MangaDownloadState.resolving'));
      expect(manga, contains('MediaDownloadJobPhase.resolving'));
      expect(manga, contains('MangaDownloadState.verifying'));
      expect(manga, contains('MediaDownloadJobPhase.verifying'));
      expect(manga, isNot(contains('DownloadStatus')));
    },
  );
}
